/* saleson.shop.order.givepoint.OrderGivePointMapper.getGiveUsePoint */ SELECT CUP.CNTR_SN , CUP.USE_SN , CUP.CNTR_USE_POINT , CUP.USER_ID , CUP.CNTR_LOCGOV_CODE , CUP.ORDER_CODE , C.POINT_END_DE FROM G_CNTR_USE_POINT CUP JOIN G_CNTR C ON CUP.CNTR_SN = C.CNTR_SN AND C.DELETE_AT = 'N' AND C.STTEMNT_PAY_DE IS NOT NULL AND C.CNTR_STTUS_CODE = '200' WHERE ORDER_CODE = #{orderCode}
AND CUP.CNTR_LOCGOV_CODE = #{cntrLocgovCode}
