/* saleson.shop.order.givepoint.OrderGivePointMapper.getCntrPointList */ SELECT CNTR_SN , CNTR_DE , USER_ID , CNTR_LOCGOV_CODE , CNTR_POINT , CASE WHEN CNTR_BLCE_POINT >= 0 THEN CNTR_BLCE_POINT
ELSE 0 END AS CNTR_BLCE_POINT FROM ( SELECT CNTR_SN , CNTR_DE , USER_ID , CNTR_LOCGOV_CODE , CNTR_POINT
, (CNTR_POINT - IFNULL((SELECT SUM(CNTR_USE_POINT) FROM G_CNTR_USE_POINT WHERE CNTR_SN = CNTR.CNTR_SN), 0)) AS CNTR_BLCE_POINT FROM G_CNTR CNTR WHERE CNTR_SN IN
#{usePoint.cntrSn}
ORDER BY CNTR_SN DESC )

