    /* saleson.shop.order.givepoint.OrderGivePointMapper.updateItemOptionStock */
		UPDATE	OP_ITEM_OPTION
		SET		OPTION_STOCK_QUANTITY = OPTION_STOCK_QUANTITY - #{buyQuantity}
		WHERE	ITEM_ID = #{itemId}
		AND		OPTION_STOCK_FLAG = 'Y'
		AND		OPTION_STOCK_QUANTITY > 0
		AND		OPTION_NAME1 like '%' || #{optionName1} || '%'
		AND		OPTION_NAME2 like '%' || #{optionName2} || '%'
		AND		OPTION_NAME3 like '%' || #{optionName3} || '%'

    /* saleson.shop.order.givepoint.OrderGivePointMapper.updateItemOptionStock */
		UPDATE	OP_ORDER_ITEM
		SET		OFF_PROC_YN = 'Y'
		WHERE	ORDER_CODE = #{orderCode}
